fixtures.mobile/note_queue.ts:
const pending: Note[] = [];
export function enqueue(note: Note) { pending.push(note); }
export async function flush(send: (n: Note) => Promise<void>) {
  while (pending.length) {
    const note = pending.shift()!;
    await send(note);
  }
}
export function queuedIds() { return pending.map(n => n.id); }

